package io.github.ningpp.compat;

import java.nio.charset.StandardCharsets;

/**
 * Replacement for System.Buffers.Text.Base64 (generated by CSharpToJava converter).
 */
public final class Base64 {
    private Base64() {
    }

    /** Mirrors Base64.GetMaxEncodedToUtf8Length(int) — ((n + 2) / 3) * 4. */
    public static int getMaxEncodedToUtf8Length(int length) {
        return ((length + 2) / 3) * 4;
    }

    /**
     * Mirrors Base64.EncodeToUtf8(ReadOnlySpan&lt;byte&gt;, Span&lt;byte&gt;, out int, out int).
     * Returns OperationStatus.Done when the destination is large enough.
     */
    public static OperationStatus encodeToUtf8(ReadOnlySpan<Integer> source, Span<Integer> destination,
                                               IntHolder bytesConsumed, IntHolder bytesWritten) {
        byte[] input = new byte[source.length()];
        for (int i = 0; i < source.length(); i++) {
            input[i] = (byte) (source.get(i) & 0xFF);
        }
        byte[] encoded = java.util.Base64.getEncoder().encode(input);
        if (encoded.length > destination.length()) {
            return OperationStatus.DestinationTooSmall;
        }
        for (int i = 0; i < encoded.length; i++) {
            destination.set(i, encoded[i] & 0xFF);
        }
        bytesConsumed.value = source.length();
        bytesWritten.value = encoded.length;
        return OperationStatus.Done;
    }
}
